\documentclass[11pt]{amsart}

\usepackage{amsmath, amssymb, amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}

\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}

\newcommand{\bin}[2]{\binom{#1}{#2}}

\title{An Exact Clique-to-Clique Count Bound and the Antitonicity of
Normalized Clique Densities}
\author{Aristotle}
\date{July 12, 2026}

\begin{document}

\begin{abstract}
For a finite simple graph $G$ on $n$ vertices and an integer $r \ge 0$, let
$k_r(G)$ denote the number of $r$-cliques of $G$. We establish an exact,
unconditional inequality comparing the clique counts of any two orders
$s \le t$:
\[
  \binom{t}{s}\,k_t(G) \;\le\; \binom{n-s}{t-s}\,k_s(G).
\]
The proof is a two-way count of incident flags $(S,T)$ with $S \subseteq T$, $S$
an $s$-clique and $T$ a $t$-clique. The inequality is \emph{tight}: it holds with
equality for the complete graph $K_n$, where both sides equal
$\binom{n}{t}\binom{t}{s} = \binom{n}{s}\binom{n-s}{t-s}$. Consequently, the
\emph{normalized clique density} $d_r(G) = k_r(G)/\binom{n}{r}$ is non-increasing
in $r$: for $s \le t \le n$,
\[
  \frac{k_t(G)}{\binom{n}{t}} \;\le\; \frac{k_s(G)}{\binom{n}{s}}.
\]
This is the unconditional \emph{upper} companion to the
Lov\'asz--Simonovits--Reiher clique density theorem, whose sharp \emph{lower}
bound is governed by complete multipartite graphs rather than the complete graph.
We discuss why the two results run in opposite directions, give the
specialization to the edge-to-clique case $s=2$, record the monotonicity of
clique counts under edge addition, and outline conjectural extensions.
\end{abstract}

\maketitle

\section{Introduction}

Counting complete subgraphs is one of the foundational problems of extremal graph
theory. Given a finite simple graph $G$, the \emph{$r$-clique count} $k_r(G)$
records how many $r$-element vertex sets induce a complete subgraph. The counts
$k_2(G), k_3(G), k_4(G), \dots$ form a profile encoding much of the graph's
structure, and a recurring theme is to understand how the entries constrain one
another.

The most celebrated result in this direction is the \emph{clique density
theorem}. Lov\'asz and Simonovits conjectured, and Reiher proved, a sharp
\emph{lower} bound on the density of $t$-cliques in terms of the density of edges
(and more generally of $s$-cliques): a graph with many edges is forced to contain
many triangles, tetrahedra, and so on, with the extremal threshold achieved by
balanced complete multipartite graphs.

This paper isolates and proves the complementary half: an \emph{upper} bound. We
ask how many $t$-cliques a graph can have relative to its number of $s$-cliques,
and find that the answer is governed by the single densest graph, the complete
graph. The inequality is exact, unconditional, and tight, and from it we derive
that the \emph{normalized} clique density---the fraction of potential $r$-cliques
actually present---never increases with $r$.

\subsection{Summary of results}
Throughout, $G$ is a finite simple graph on $n = |V(G)|$ vertices, and
$\binom{a}{b}$ is the binomial coefficient (equal to $0$ when $b > a$).
\begin{itemize}
  \item \textbf{Theorem~\ref{thm:sub}}: every $t$-clique contains exactly
    $\binom{t}{s}$ sub-$s$-cliques.
  \item \textbf{Theorem~\ref{thm:ext}}: every $s$-clique is contained in at most
    $\binom{n-s}{t-s}$ super-$t$-cliques.
  \item \textbf{Theorem~\ref{thm:bound}}:
    $\binom{t}{s}\,k_t(G) \le \binom{n-s}{t-s}\,k_s(G)$.
  \item \textbf{Theorem~\ref{thm:tight}}: equality holds for $G = K_n$.
  \item \textbf{Theorem~\ref{thm:antitone}}:
    $k_t(G)/\binom{n}{t} \le k_s(G)/\binom{n}{s}$ for $s \le t \le n$.
\end{itemize}

\section{Definitions}

\begin{definition}[Graph, adjacency]
A \emph{finite simple graph} $G$ consists of a finite vertex set $V(G)$ and a
symmetric, irreflexive adjacency relation; for $u,v \in V(G)$ we write $u \sim v$
when $\{u,v\}$ is an edge. We set $n = |V(G)|$.
\end{definition}

\begin{definition}[Clique]
A subset $S \subseteq V(G)$ is a \emph{clique} if every two distinct vertices of
$S$ are adjacent. If $|S| = r$ we call $S$ an \emph{$r$-clique}.
\end{definition}

\begin{definition}[Clique count]
For $r \ge 0$, the \emph{$r$-clique count} is
$k_r(G) = \#\{ S \subseteq V(G) : S \text{ is an } r\text{-clique} \}$.
In particular $k_0(G) = 1$, $k_1(G) = n$, and $k_2(G)$ is the number of edges.
\end{definition}

\begin{definition}[Normalized clique density]
For $0 \le r \le n$, the \emph{normalized $r$-clique density} is
$d_r(G) = k_r(G)/\binom{n}{r} \in [0,1]$, the proportion of the $\binom{n}{r}$
potential $r$-subsets that are cliques. Note $d_r(K_n) = 1$ for all
$0 \le r \le n$.
\end{definition}

\begin{lemma}[Heredity]\label{lem:hered}
Any subset of a clique is a clique.
\end{lemma}
\begin{proof}
If every pair in $S$ is adjacent and $S' \subseteq S$, then every pair in $S'$ is
a pair in $S$, hence adjacent.
\end{proof}

\begin{lemma}[Complete graph clique count]\label{lem:kn}
For the complete graph $K_n$, $k_r(K_n) = \binom{n}{r}$ for all $0 \le r \le n$.
\end{lemma}
\begin{proof}
In $K_n$ every pair of vertices is adjacent, so every $r$-subset is a clique;
there are $\binom{n}{r}$ of them.
\end{proof}

\section{The two local counts}

The argument rests on understanding the incidence between $s$-cliques and
$t$-cliques one clique at a time.

\begin{theorem}[Sub-clique count]\label{thm:sub}
Let $T$ be a $t$-clique of $G$ and $0 \le s \le t$. Then the number of
$s$-cliques of $G$ contained in $T$ equals $\binom{t}{s}$.
\end{theorem}
\begin{proof}
The $s$-cliques of $G$ contained in $T$ are exactly the $s$-element subsets of
$T$. Indeed, an $s$-clique contained in $T$ is in particular an $s$-subset of $T$;
conversely, any $s$-subset $S \subseteq T$ is a clique by Heredity
(Lemma~\ref{lem:hered}), hence an $s$-clique. The number of $s$-subsets of the
$t$-element set $T$ is $\binom{t}{s}$.
\end{proof}

\begin{theorem}[Extension bound]\label{thm:ext}
Let $S$ be an $s$-clique of $G$ and $s \le t$. Then the number of $t$-cliques of
$G$ containing $S$ is at most $\binom{n-s}{t-s}$.
\end{theorem}
\begin{proof}
Let $\mathcal{T}$ be the set of $t$-cliques $T$ with $S \subseteq T$. Define
$\varphi(T) = T \setminus S$. For $T \in \mathcal{T}$ we have
$T \setminus S \subseteq V(G) \setminus S$ and
$|T \setminus S| = t - s$, so $\varphi$ maps $\mathcal{T}$ into the family of
$(t-s)$-subsets of the $n-s$ vertices outside $S$. It is injective: from
$T \supseteq S$ we recover $T = (T \setminus S) \cup S$, which depends only on
$\varphi(T)$. Hence $|\mathcal{T}| \le \binom{n-s}{t-s}$.
\end{proof}

Inequality, rather than equality, enters only here: not every $(t-s)$-subset of
the outside vertices need extend $S$ to a clique. Equality holds precisely when
every extension is a clique, i.e.\ when the graph is complete on the relevant
vertices.

\section{The clique-to-clique count bound}

A \emph{flag} is a pair $(S,T)$ where $S$ is an $s$-clique, $T$ is a $t$-clique,
and $S \subseteq T$.

\begin{theorem}[Clique-to-clique count bound]\label{thm:bound}
For every finite simple graph $G$ on $n$ vertices and all $s, t \ge 0$,
\[
  \binom{t}{s}\,k_t(G) \;\le\; \binom{n-s}{t-s}\,k_s(G).
\]
\end{theorem}
\begin{proof}
Let $N$ be the number of flags, counted two ways. Grouping by the $t$-clique $T$,
each contributes $\binom{t}{s}$ sub-$s$-cliques (Theorem~\ref{thm:sub}), so
$N = \binom{t}{s}\,k_t(G)$. Grouping by the $s$-clique $S$, each admits at most
$\binom{n-s}{t-s}$ super-$t$-cliques (Theorem~\ref{thm:ext}), so
$N \le \binom{n-s}{t-s}\,k_s(G)$. Equating gives the claim.
\end{proof}

When $t < s$ the statement is trivial, since $\binom{t}{s} = 0$; the content is
the case $s \le t$.

\section{Tightness}

\begin{theorem}[Tightness on the complete graph]\label{thm:tight}
For $s \le t \le n$, the bound of Theorem~\ref{thm:bound} holds with equality for
$G = K_n$; both sides equal
$\binom{n}{t}\binom{t}{s} = \binom{n}{s}\binom{n-s}{t-s}$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:kn}, $k_r(K_n) = \binom{n}{r}$. The two sides become
$\binom{t}{s}\binom{n}{t}$ and $\binom{n-s}{t-s}\binom{n}{s}$, equal by the
subset-of-a-subset identity
\begin{equation}\label{eq:star}
  \binom{n}{t}\binom{t}{s} \;=\; \binom{n}{s}\binom{n-s}{t-s},
\end{equation}
which counts the pairs $B \subseteq A \subseteq V$ with $|B| = s$, $|A| = t$ in
two ways.
\end{proof}

Thus the binomial constants in Theorem~\ref{thm:bound} are best possible.

\section{Antitonicity of normalized clique density}

\begin{theorem}[Antitonicity]\label{thm:antitone}
Let $G$ be a finite simple graph on $n$ vertices and $0 \le s \le t \le n$. Then
\[
  k_t(G)\,\binom{n}{s} \;\le\; k_s(G)\,\binom{n}{t},
  \qquad\text{equivalently}\qquad
  \frac{k_t(G)}{\binom{n}{t}} \;\le\; \frac{k_s(G)}{\binom{n}{s}}.
\]
That is, $d_r(G) = k_r(G)/\binom{n}{r}$ is non-increasing in $r$ on
$0 \le r \le n$.
\end{theorem}
\begin{proof}
Multiply Theorem~\ref{thm:bound} by $\binom{n}{s}$:
\[
  \binom{t}{s}\,k_t\,\binom{n}{s}
  \;\le\; \binom{n-s}{t-s}\,\binom{n}{s}\,k_s
  \;=\; \binom{n}{t}\,\binom{t}{s}\,k_s,
\]
using \eqref{eq:star}. Since $s \le t$, $\binom{t}{s} > 0$; cancelling it gives
$k_t\,\binom{n}{s} \le k_s\,\binom{n}{t}$. For $s \le t \le n$ both binomials are
positive, so dividing yields the ratio form.
\end{proof}

The reading is memorable: the fraction of potential cliques realized by a graph
can only decrease as the order grows, with equality across all orders achieved
exactly by $K_n$.

\section{Corollaries and remarks}

\begin{corollary}[Edge-to-clique bound]
Since the $2$-cliques are the edges, taking $s = 2$ gives
$\binom{t}{2}\,k_t(G) \le \binom{n-2}{t-2}\,k_2(G)$.
\end{corollary}

\begin{corollary}[Monotonicity under edge addition]
If $G$ is a spanning subgraph of $H$, then $k_r(G) \le k_r(H)$ for all $r$, since
every clique of $G$ remains a clique of $H$.
\end{corollary}

\begin{remark}
The argument is entirely local, counting within or around one clique via subset
arithmetic. Locality is why the extremal object is the complete graph and why the
bound is an \emph{upper} bound. The matching \emph{lower} bound requires global
averaging and is governed by complete multipartite graphs; this reversal of
extremal regime is the structural reason the two theorems are complementary.
\end{remark}

\section{The complementary lower bound}

Define, for each order $r$, the Lov\'asz--Simonovits function $F_r$ tracing the
minimum $r$-clique density $k_r(G)/n^r$ along balanced complete multipartite
graphs; $F_r$ is a piecewise-linear/convex profile and $F_s^{-1}$ its
generalized inverse. The \emph{clique density theorem} (Reiher, for $s=2$)
asserts that for all $2 \le s < t$ and every $n$-vertex $G$,
\[
  \frac{k_t(G)}{n^t}
  \;\ge\; F_t\!\left(F_s^{-1}\!\left(\frac{k_s(G)}{n^s}\right)\right).
\]
Here the extremal graphs are complete multipartite. Together with
Theorem~\ref{thm:antitone}, this brackets the clique-density profile between an
upper wall (the complete graph) and a lower wall (multipartite blow-ups).

\section{Applications and future directions}

The clique-count profile is a workhorse statistic in network science.
Theorem~\ref{thm:antitone} yields a free, tight upper certificate:
from the edge density $d_2(G)$ one bounds every higher $d_r(G) \le d_2(G)$;
monotonicity under edge addition quantifies how sparsification reduces all
higher counts; and near-equality signatures flag dense clique-like communities.

Future targets include: (1) the sharp clique-to-clique lower bound
$k_t/n^t \ge F_t(F_s^{-1}(k_s/n^s))$ for all $2 \le s < t$; (2) a stability
theorem showing $d_t(G) \approx d_s(G)$ forces $G$ close to a disjoint union of
cliques; (3) a graphon avatar via a Fubini exchange of clique integrals; and
(4) monotone density profiles for general subgraph patterns beyond cliques.

\section{Conclusion}

The short, exact, tight inequality
$\binom{t}{s}\,k_t(G) \le \binom{n-s}{t-s}\,k_s(G)$ captures how the number of
large cliques in any finite graph is controlled by the number of small ones. Its
corollary---the antitonicity of the normalized clique density
$d_r(G) = k_r(G)/\binom{n}{r}$---is the unconditional upper half of the
clique-density story, complementing the deep lower bounds of
Lov\'asz--Simonovits--Reiher, with the complete graph as the single extremal
object throughout.

\begin{thebibliography}{9}
\bibitem{Reiher} C.~Reiher, \emph{The clique density theorem}, Annals of
Mathematics (2016).
\bibitem{LS} L.~Lov\'asz and M.~Simonovits, \emph{On the number of complete
subgraphs of a graph II}, Studies in Pure Mathematics (1983).
\bibitem{Bollobas} B.~Bollob\'as, \emph{Complete subgraphs are elusive}, Journal
of Combinatorial Theory, Series B (1976).
\end{thebibliography}

