"""Demo: clique counts and the two-way flag count that proves the bound."""
from itertools import combinations
from math import comb
from typing import List, Tuple, Set, FrozenSet

def clique_count(n: int, adj: Set[FrozenSet[int]], r: int) -> int:
    if r == 0:
        return 1
    return sum(1 for c in combinations(range(n), r)
               if all(frozenset((u, v)) in adj for u, v in combinations(c, 2)))

def flags(n: int, adj: Set[FrozenSet[int]], s: int, t: int) -> int:
    """Count incident pairs (S, T): S an s-clique, T a t-clique, S subset of T."""
    def is_clq(c): return all(frozenset((u, v)) in adj for u, v in combinations(c, 2))
    S = [set(c) for c in combinations(range(n), s) if is_clq(c)]
    T = [set(c) for c in combinations(range(n), t) if is_clq(c)]
    return sum(1 for a in S for b in T if a <= b)

if __name__ == "__main__":
    n = 6
    adj = {frozenset((u, v)) for u, v in combinations(range(n), 2)}  # K_6
    for s in range(2, 5):
        for t in range(s, 6):
            N = flags(n, adj, s, t)
            top = comb(t, s) * clique_count(n, adj, t)
            bot = comb(n - s, t - s) * clique_count(n, adj, s)
            print(f"s={s} t={t}: flags={N}  top-down={top}  bottom-up-bound={bot}")

"""Demo: tightness on K_n and the subset-of-a-subset identity."""
from math import comb
from typing import Tuple

def sides(n: int, s: int, t: int) -> Tuple[int, int]:
    """For K_n: left = C(t,s)*C(n,t), right = C(n-s,t-s)*C(n,s)."""
    left = comb(t, s) * comb(n, t)
    right = comb(n - s, t - s) * comb(n, s)
    return left, right

if __name__ == "__main__":
    for n in range(3, 9):
        ok = all(sides(n, s, t)[0] == sides(n, s, t)[1]
                 for s in range(0, n + 1) for t in range(s, n + 1))
        print(f"K_{n}: equality C(n,t)C(t,s) = C(n,s)C(n-s,t-s) for all s<=t<=n? {ok}")

