def count_bound(n: int, adj: Set[FrozenSet[int]], s: int, t: int) -> Tuple[int, int, bool]:
    """Return (lhs, rhs, holds) for C(t,s)*k_t <= C(n-s,t-s)*k_s."""
    lhs = comb(t, s) * clique_count(n, adj, t)
    rhs = comb(n - s, t - s) * clique_count(n, adj, s)
    return lhs, rhs, lhs <= rhs

