"""Visualization: the two-way flag count as a bipartite incidence."""
import matplotlib.pyplot as plt
from itertools import combinations

n, s, t = 5, 2, 3
adj = {frozenset((u, v)) for u, v in combinations(range(n), 2)}  # K_5
def is_clq(c): return all(frozenset((u, v)) in adj for u, v in combinations(c, 2))
S = [c for c in combinations(range(n), s) if is_clq(c)]
T = [c for c in combinations(range(n), t) if is_clq(c)]

fig, ax = plt.subplots(figsize=(9, 6))
ys_S = {c: i for i, c in enumerate(S)}
ys_T = {c: i for i, c in enumerate(T)}
for c, y in ys_S.items():
    ax.text(0, y, str(c), ha="right", va="center", fontsize=8)
for c, y in ys_T.items():
    ax.text(1, y, str(c), ha="left", va="center", fontsize=8)
for a in S:
    for b in T:
        if set(a) <= set(b):
            ax.plot([0, 1], [ys_S[a], ys_T[b]], color="steelblue", alpha=0.5)
ax.set_xlim(-0.3, 1.3); ax.axis("off")
ax.set_title(f"Flags (S,T): each t-clique has C(t,s)={len(T) and __import__('math').comb(t,s)} sub-s-cliques (K_{n})")
plt.tight_layout(); plt.savefig("flag_incidence.png", dpi=150)
print("saved flag_incidence.png")
